// Perspective triangle renderer for browsers without WebGL. Uses the same scene,
// skeletal animation and 3D transforms as the hardware renderer.
import * as T from 'three';
export class SoftwareRenderer{
 constructor(canvas){this.domElement=canvas;this.ctx=canvas.getContext('2d',{alpha:false});this.textures=new WeakMap();this.ratio=1;this.maxActors=5;this.faces=[];this.sprites=[];this.lines=[];this.v=new T.Vector3();this.mv=new T.Matrix4();this.tmp=new T.Matrix4();this.instance=new T.Matrix4();this.light=new T.Vector3(-.35,.85,.4).normalize();}
 setPixelRatio(r){this.ratio=Math.min(r,1);}
 setSize(w,h){this.width=w;this.height=h;this.domElement.width=Math.round(w*this.ratio);this.domElement.height=Math.round(h*this.ratio);}
 texture(map){if(!map?.image)return null;if(this.textures.has(map))return this.textures.get(map);try{const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(map.image,0,0,128,128);const data=ctx.getImageData(0,0,128,128).data;this.textures.set(map,data);return data;}catch{this.textures.set(map,null);return null;}}
 project(p,camera){const v=p.clone().applyMatrix4(camera.matrixWorldInverse);if(v.z>-.2)return null;const z=-v.z;v.applyMatrix4(camera.projectionMatrix);return {x:(v.x*.5+.5)*this.domElement.width,y:(-.5*v.y+.5)*this.domElement.height,z};}
 mesh(o,camera,matrix,fog){const geom=o.geometry,pos=geom.attributes.position;if(!pos)return;const materials=Array.isArray(o.material)?o.material:[o.material],ind=geom.index,uv=geom.attributes.uv,count=ind?ind.count:pos.count;const points=new Array(pos.count),world=new Array(pos.count);
 if(o.isSkinnedMesh)o.skeleton.update();
 for(let i=0;i<pos.count;i++){const v=new T.Vector3().fromBufferAttribute(pos,i);if(o.isSkinnedMesh)o.applyBoneTransform(i,v);v.applyMatrix4(matrix);world[i]=v;points[i]=this.project(v,camera);}
 const groups=geom.groups.length?geom.groups:[{start:0,count,materialIndex:0}];
 for(const group of groups){const m=materials[group.materialIndex]||materials[0];if(!m||!m.visible||m.opacity<.02)continue;const tex=this.texture(m.map),color=m.color||new T.Color('#ffffff');for(let i=group.start;i<Math.min(count,group.start+group.count);i+=3){const a=ind?ind.getX(i):i,b=ind?ind.getX(i+1):i+1,c=ind?ind.getX(i+2):i+2,A=points[a],B=points[b],C=points[c];if(!A||!B||!C)continue;const area=(B.x-A.x)*(C.y-A.y)-(B.y-A.y)*(C.x-A.x);if(m.side!==T.DoubleSide&&area>=0)continue;if(Math.abs(area)<.09)continue;if(Math.max(A.x,B.x,C.x)<0||Math.min(A.x,B.x,C.x)>this.domElement.width||Math.max(A.y,B.y,C.y)<0||Math.min(A.y,B.y,C.y)>this.domElement.height)continue;const depth=(A.z+B.z+C.z)/3;if(depth>180)continue;
 const normal=new T.Vector3().subVectors(world[b],world[a]).cross(new T.Vector3().subVectors(world[c],world[a])).normalize();let shade=o.material?.isMeshBasicMaterial?1:.48+Math.max(0,normal.dot(this.light))*.65;let r=255*color.r,g=255*color.g,bl=255*color.b,alpha=m.opacity??1;
 if(tex&&uv){let u=(uv.getX(a)+uv.getX(b)+uv.getX(c))/3,v=(uv.getY(a)+uv.getY(b)+uv.getY(c))/3;if(m.map.flipY)v=1-v;u=u*m.map.repeat.x+m.map.offset.x;v=v*m.map.repeat.y+m.map.offset.y;u=(u%1+1)%1;v=(v%1+1)%1;const at=(Math.floor(v*127)*128+Math.floor(u*127))*4;r*=tex[at]/255;g*=tex[at+1]/255;bl*=tex[at+2]/255;alpha*=tex[at+3]/255;if(alpha<.2)continue;}
 r*=shade;g*=shade;bl*=shade;if(m.emissive){r+=m.emissive.r*100;g+=m.emissive.g*100;bl+=m.emissive.b*100;}const f=fog?Math.min(.93,1-Math.exp(-depth*depth*(fog.density||.009)**2)):0;if(fog){r=r*(1-f)+fog.color.r*255*f;g=g*(1-f)+fog.color.g*255*f;bl=bl*(1-f)+fog.color.b*255*f;}this.faces.push({a:A,b:B,c:C,z:depth,color:`rgb(${Math.min(255,r)|0},${Math.min(255,g)|0},${Math.min(255,bl)|0})`,alpha});}}
 }
 render(scene,camera){scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);const ctx=this.ctx,w=this.domElement.width,h=this.domElement.height,bg=scene.background?.isColor?scene.background:new T.Color('#74958b');const gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'#263c47');gradient.addColorStop(.5,bg.getStyle());gradient.addColorStop(1,'#192c2b');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);const sun=ctx.createRadialGradient(w*.73,h*.2,0,w*.73,h*.2,h*.3);sun.addColorStop(0,'rgba(255,232,182,.35)');sun.addColorStop(.2,'rgba(255,222,170,.09)');sun.addColorStop(1,'rgba(255,222,170,0)');ctx.fillStyle=sun;ctx.fillRect(0,0,w,h);this.faces=[];this.sprites=[];this.lines=[];const actorRoots=[];scene.traverseVisible(o=>{if(o.userData.actor)actorRoots.push(o);});actorRoots.sort((a,b)=>b.position.z-a.position.z);const detailed=new Set(actorRoots.slice(0,this.maxActors));
 scene.traverseVisible(o=>{let root=o;while(root&&!root.userData.actor)root=root.parent;if(root&&!detailed.has(root)&&o.isSkinnedMesh)return;if(o.isMesh){if(o.isInstancedMesh){for(let i=0;i<Math.min(o.count,70);i++){o.getMatrixAt(i,this.instance);this.tmp.multiplyMatrices(o.matrixWorld,this.instance);this.mesh(o,camera,this.tmp,scene.fog);}}else this.mesh(o,camera,o.matrixWorld,scene.fog);}else if(o.isSprite)this.sprites.push(o);else if(o.isLine)this.lines.push(o);});
 this.faces.sort((a,b)=>b.z-a.z);for(const f of this.faces){ctx.globalAlpha=f.alpha;ctx.fillStyle=f.color;ctx.beginPath();ctx.moveTo(f.a.x,f.a.y);ctx.lineTo(f.b.x,f.b.y);ctx.lineTo(f.c.x,f.c.y);ctx.closePath();ctx.fill();}ctx.globalAlpha=1;
 for(const root of actorRoots){if(detailed.has(root))continue;const e=root.userData.entity;if(!e.alive)continue;const p=this.project(new T.Vector3(e.x,e.y,e.z),camera),foot=this.project(new T.Vector3(e.x,0,e.z),camera);if(!p||!foot)continue;const height=Math.abs(foot.y-p.y)*1.85,width=height*.27;ctx.fillStyle=e.type==='skeleton'?'#c6c2aa':e.type==='runner'?'#773e44':'#39484b';ctx.fillRect(p.x-width/2,p.y-height*.22,width,height*.5);ctx.beginPath();ctx.ellipse(p.x,p.y-height*.38,width*.44,width*.52,0,0,Math.PI*2);ctx.fill();ctx.lineWidth=Math.max(1,width*.3);ctx.strokeStyle=ctx.fillStyle;const stride=Math.sin(e.age*7+e.phase)*width*.55;ctx.beginPath();ctx.moveTo(p.x-width*.22,p.y+height*.2);ctx.lineTo(p.x-width*.3+stride,foot.y);ctx.moveTo(p.x+width*.22,p.y+height*.2);ctx.lineTo(p.x+width*.3-stride,foot.y);ctx.stroke();ctx.fillStyle='#f4b18f';ctx.fillRect(p.x-width*.25,p.y-height*.4,width*.5,Math.max(1,width*.1));}
 for(const o of this.lines){const pos=o.geometry.attributes.position;if(pos.count<2)continue;const A=this.project(new T.Vector3().fromBufferAttribute(pos,0).applyMatrix4(o.matrixWorld),camera),B=this.project(new T.Vector3().fromBufferAttribute(pos,1).applyMatrix4(o.matrixWorld),camera);if(!A||!B)continue;ctx.globalAlpha=o.material.opacity;ctx.strokeStyle=o.material.color.getStyle();ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(A.x,A.y);ctx.lineTo(B.x,B.y);ctx.stroke();}ctx.globalAlpha=1;
 for(const o of this.sprites){const pos=o.getWorldPosition(this.v),p=this.project(pos,camera);if(!p)continue;const size=Math.min(60,Math.abs(o.scale.x*camera.projectionMatrix.elements[0]/p.z*w*.5));const color=o.material.color||new T.Color('#ffc58e');ctx.globalAlpha=o.material.opacity;const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,Math.max(.1,size));g.addColorStop(0,color.getStyle());g.addColorStop(1,'rgba(255,200,150,0)');ctx.fillStyle=g;ctx.fillRect(p.x-size,p.y-size,size*2,size*2);}ctx.globalAlpha=1;
 }
}
